jQuery(document).ready(function(a){if(0!==a(".dw-frontend-wrapper").length){function b(){a(".dw-stat-value").addClass("dw-skeleton"),a.ajax({url:dw_dashboard_vars.ajax_url,type:"POST",data:{action:"dw_get_dashboard_stats",nonce:dw_dashboard_vars.nonce},success:function(b){b.success&&(a("#stat-sales").text(b.data.sales),a("#stat-orders").text(b.data.orders),a("#stat-products").text(b.data.products))},complete:function(){a(".dw-stat-value").removeClass("dw-skeleton")},error:function(){a(".dw-stat-value").removeClass("dw-skeleton").text("Err")}}) }function c(){var b=a("#dw-transaction-table tbody");if(!(b.find(".no-data").length>0)){a.ajax({url:dw_dashboard_vars.ajax_url,type:"POST",data:{action:"dw_get_recent_transactions",nonce:dw_dashboard_vars.nonce},success:function(c){c.success&&c.data.html?b.html(c.data.html):c.success&&!c.data.html&&b.html('<tr><td colspan="5" class="no-data" style="text-align:center; padding: 20px;">Belum ada transaksi.</td></tr>')}})}}b(),c(),setInterval(function(){a.ajax({url:dw_dashboard_vars.ajax_url,type:"POST",data:{action:"dw_get_dashboard_stats",nonce:dw_dashboard_vars.nonce},success:function(b){b.success&&(a("#stat-sales").text(b.data.sales),a("#stat-orders").text(b.data.orders),a("#stat-products").text(b.data.products))}})},6e4),window.dwRefreshOjekList=function(){b(),c(),console.log("Dashboard refreshed")}}});